import os,pty,select,time,fcntl,termios,struct,signal,re

def cap(args, rows=8, cols=50):
    pid, fd=pty.fork()
    if pid==0:
        os.environ['TERM']='xterm-256color'
        os.execv('./executable',['./executable']+args)
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH',rows,cols,0,0))
    out=b''; start=time.time(); sent=False
    while time.time()-start<1.2:
        r,_,_=select.select([fd],[],[],0.05)
        if r:
            try: out+=os.read(fd,4096)
            except OSError: break
        if not sent and time.time()-start>0.6:
            os.write(fd,b'q'); sent=True
    try: os.kill(pid, signal.SIGTERM)
    except: pass
    s=out.decode('utf-8','replace')
    # extract text chars roughly by stripping csi/osc
    s=re.sub(r'\x1b\][^\x1b]*(?:\x1b\\|\x07)','',s)
    s=re.sub(r'\x1b\[[0-?]*[ -/]*[@-~]','',s)
    s=re.sub(r'\x1b[()][0-9A-Za-z]','',s)
    s=re.sub(r'\x1b[=>c]','',s)
    return s[-1000:]
for args in [ ['-n','testdata/test3.txt'], ['--skip-lines','2','testdata/test3.txt'], ['--filter','5','testdata/test3.txt'], ['-c','testdata/test.csv'], ['-l','testdata/test.csv'], ['-H','2','testdata/test3.txt'] ]:
    print('###', args)
    print(cap(args).replace('\r','\\r'))
PY"}

